/**
 * Types for `<ViewTransition>`.
 *
 * The component ships in the React build this project runs on, but its
 * declaration lives in `@types/react`'s canary entry rather than the default
 * one — so without this reference the import type-checks as missing while
 * working perfectly in the browser, which is the worst of both answers.
 *
 * A reference rather than a hand-written shim: the props are React's to define,
 * and a copy here would be a second definition to keep in step with the first.
 */
/// <reference types="react/canary" />
